import { z } from 'zod';

/**
 * Identifier types. "Branded" means TypeScript treats them as distinct from plain strings:
 * a function that takes a `Uuid` won't accept an arbitrary string until it has been parsed
 * with `Uuid.parse()`. The brand exists only in types; at runtime they are ordinary strings.
 */

/** A row id: a UUID, generated by Postgres as UUIDv7 (data-model §2). */
export const Uuid = z.uuid().brand<'Uuid'>();
export type Uuid = z.infer<typeof Uuid>;

/** A URL-safe name: lower-case letters and digits in hyphen-separated words (data-model §2). */
export const Slug = z
  .string()
  .min(1)
  .max(100)
  .regex(/^[a-z0-9]+(-[a-z0-9]+)*$/, 'Use lower-case letters and digits, separated by hyphens.')
  .brand<'Slug'>();
export type Slug = z.infer<typeof Slug>;
